const WORDS = [
  "apple", "river", "cloud", "tiger", "pencil", "mountain", "coffee", "window",
  "garden", "rocket", "violin", "pepper", "harbor", "lantern", "marble", "thunder",
  "orange", "puzzle", "shadow", "compass", "meadow", "button", "canyon", "whisper"
];
const TOTAL = 1000;
const batchId = Date.now();

for (let i = 1; i <= TOTAL; i++) {
  const len = 4 + Math.floor(Math.random() * 7); // 4 to 10 inclusive
  const arr = Array.from({ length: len }, () =>
    WORDS[Math.floor(Math.random() * WORDS.length)]
  );
  node.send({ payload: arr, seq: i, total: TOTAL, batchId: batchId });
}

node.status({ fill: "blue", shape: "dot", text: "sent " + TOTAL });
return null;

const TIMEOUT_MS = 10000;

// Ignore late messages from a batch that has already been reported (e.g. after a timeout)
if (msg.batchId !== undefined && msg.batchId === context.get('doneBatch')) {
  return null;
}

let st = context.get('st');
if (!st) {
  st = {
    batchId: msg.batchId,
    expected: msg.total || 1000,
    count: 0,
    start: Date.now(),
    last: Date.now(),
    timer: null
  };
  st.timer = setTimeout(() => finish(true), TIMEOUT_MS);
  context.set('st', st);
  node.status({ fill: "yellow", shape: "ring", text: "receiving..." });
}

st.count++;
st.last = Date.now();

if (st.count >= st.expected) {
  finish(false);
}
return null;

function finish(timedOut) {
  const s = context.get('st');
  if (!s) return;
  clearTimeout(s.timer);
  context.set('doneBatch', s.batchId);
  context.set('st', null);

  const elapsedMs = s.last - s.start; // first message -> last message received
  node.send({
    payload: {
      expected: s.expected,
      received: s.count,
      timedOut: timedOut,
      elapsedMs: elapsedMs,
      msgPerSec: elapsedMs > 0 ? Math.round(s.count / (elapsedMs / 1000)) : null,
      note: timedOut ? "Timed out after " + (TIMEOUT_MS / 1000) + "s" : "All messages received"
    }
  });
  node.status({
    fill: timedOut ? "red" : "green",
    shape: "dot",
    text: s.count + "/" + s.expected + " in " + elapsedMs + " ms"
  });
}
